import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <mma.h>

#define TILE_SIZE 32
#define WARPS_PER_BLOCK 4
#define THREADS_PER_WARP 32

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    // Warp and lane identification
    const int warpId = threadIdx.x / THREADS_PER_WARP;
    const int laneId = threadIdx.x % THREADS_PER_WARP;

    // Warp-level tiling
    const int warpRow = warpId / (TILE_SIZE / THREADS_PER_WARP);
    const int warpCol = warpId % (TILE_SIZE / THREADS_PER_WARP);

    // Global coordinates
    const int row = blockIdx.y * TILE_SIZE + warpRow * THREADS_PER_WARP + laneId;
    const int col = blockIdx.x * TILE_SIZE + warpCol * THREADS_PER_WARP + laneId;

    // Register accumulation
    float sum = 0.0f;

    for (int tile = 0; tile < (K + TILE_SIZE - 1) / TILE_SIZE; ++tile) {
        // Global memory indices
        int a_index = row * K + tile * TILE_SIZE + laneId;
        int b_index = (tile * TILE_SIZE + laneId) * N + col;

        // Load directly from global memory
        float a_val = (row < M && (tile * TILE_SIZE + laneId) < K) ? A[a_index] : 0.0f;
        float b_val = ((tile * TILE_SIZE + laneId) < K && col < N) ? B[b_index] : 0.0f;

        // Warp shuffle reduction
        for (int i = 0; i < THREADS_PER_WARP; i++) {
            float a_shuffle = __shfl_sync(0xffffffff, a_val, i, THREADS_PER_WARP);
            float b_shuffle = __shfl_sync(0xffffffff, b_val, i, THREADS_PER_WARP);
            sum += a_shuffle * b_shuffle;
        }
    }

    // Write result to global memory
    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

